type Flow={id:string;owner:string;authorization_key:string;article_id:string;snapshot:string;snapshot_sha256:string;state:string;final_sha256:string|null;expires:string;created:string;updated:string};
type Step={id:string;owner:string;run_id:string;stage:EditorialStage;token:string;input_json:string;input_sha256:string;state:string;artifact_json:string|null;artifact_sha256:string|null;actor_id:string|null;execution_id:string|null;model:string|null;provenance:string|null;receipt_id:string|null;error:string|null;created:string;updated:string};
const errors={invalid:'写作链路参数无效',missing:'未找到本人的写作链路',binding:'写作链路版本或身份绑定已变化',stopped:'本次写作已暂停或归档，只能读取',phase:'前序阶段未完整通过，不能继续',expired:'本批次已过期，只能读取已有结果',confirm:'需要明确确认本次操作',unknown:'本次请求结果待核验，只读恢复，不重复请求',credential:'资料或结果安全校验未通过，内容已隐藏',capability:'主笔模型输出能力未核实，未发起请求'} as const;
export function editorialFlowPublicError(error:unknown){const m=error instanceof Error?error.message:'';return Object.values(errors).some(x=>x===m)?m:editorialPublicError(error);}
const now=()=>new Date().toISOString();
const uuid=(v:unknown):v is string=>typeof v==='string'&&/^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(v);
function keys(v:unknown,allowed:string[]):asserts v is Record<string,unknown>{if(!v||typeof v!=='object'||Array.isArray(v)||Object.keys(v).some(k=>!allowed.includes(k)))throw Error(errors.invalid);}
function text(v:unknown,max:number):asserts v is string{if(typeof v!=='string'||!v.trim()||v.length>max)throw Error(errors.invalid);}
function confirm(v:Record<string,unknown>){if(v.confirm!==true)throw Error(errors.confirm);}
const paid=(stage:EditorialStage)=>['outline','body','structure_revision','fact_revision'].includes(stage);
function stageOf(v:unknown):EditorialStage{if(!editorialStages.includes(v as EditorialStage))throw Error(errors.invalid);return v as EditorialStage;}
const role=(stage:EditorialStage)=>stage==='outline_review'?'outline_reviewer':stage==='structure_review'?'structure_reviewer':stage==='fact_check'?'fact_checker':stage==='final_verify'?'verifier':'writer';
const receiptId=(owner:string,id:string,stage:string)=>`editorial_v2:${owner}:${id}:${stage}`;
