   const bound=paid(step.stage)&&step.receipt_id===receiptId(owner,row.id,step.stage)&&result.state==='completed'&&result.stage===step.stage&&result.input_sha256===step.input_sha256&&result.snapshot_sha256===row.snapshot_sha256&&result.requested_model===s.model&&result.returned_model===s.model;
