 const derived=await deriveOutlineFormat(source,{validation_version:s.artifact_validation_version||2,sources:s.sources,facts:s.facts}),raw=JSON.stringify(derived.artifact),proof=JSON.stringify({...derived.proof,input_sha256:step.input_sha256,snapshot_sha256:row.snapshot_sha256}),time=now();await credentialFree(row.owner,{artifact:derived.artifact,proof});
