export async function editorialFlowCall(owner:string,name:string,args:unknown){if(name==='create_editorial_flow')return createEditorialFlow(owner,args);if(name==='read_editorial_flow')return readEditorialFlow(owner,args);if(name==='claim_editorial_stage')return claimEditorialStage(owner,args);if(name==='save_editorial_review')return saveEditorialReview(owner,args);if(name==='skip_editorial_revision')return skipEditorialRevision(owner,args);if(name==='recover_editorial_stage')return recoverEditorialStage(owner,args);if(name==='freeze_editorial_flow')return freezeEditorialFlow(owner,args);if(name==='dispatch_editorial_flow')return dispatchEditorialFlow(owner,args);if(['archive_editorial_flow','restore_editorial_flow','pause_editorial_flow'].includes(name))return setEditorialControl(owner,args,name.startsWith('archive')?'archived':name.startsWith('pause')?'paused':'active');throw Error(errors.invalid);}
